import json

with open('n8n/fixed_n8n_scoped_filtered_final.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

for node in data.get('nodes', []):
    if node['name'] == 'No4_transacciones':
        if 'parameters' in node:
            params = node['parameters']
            
            # Change URL to include the query generated by LLM
            # Looking at the image, 'query' value is "?skip=0&limit=5", we append {{$parameter.query}}
            # But the LLM sometimes adds '?'. To be safe we should just append it directly
            params['url'] = "={{$json.baseUrl}}/transactions/list{{$parameter.query}}"
            
            # Remove all the specific jsonQuery properties that were failing with HTTP 400
            if 'sendQuery' in params:
                del params['sendQuery']
            if 'specifyQuery' in params:
                del params['specifyQuery']
            if 'jsonQuery' in params:
                del params['jsonQuery']
            if 'parametersQuery' in params:
                del params['parametersQuery']
                
            print("Successfully updated No4_transacciones to append ?query directly to URL")

with open('n8n/fixed_n8n_scoped_filtered_final.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, indent=2)

print('Updated No4_transacciones.')
